quickstart.javascript:
import { MilvusClient } from "@zilliz/milvus2-sdk-node";

const client = new MilvusClient({ address: "localhost:19530" });
await client.createCollection({ collection_name: "docs", dimension: 3 });
await client.insert({ collection_name: "docs", data: [{ id: 1, vector: [0.1, 0.9, 0.0] }] });
console.log(await client.search({ collection_name: "docs", data: [0.1, 0.8, 0.1], limit: 1 }));
